        },
        {
          "id": "delete_trigger_btn",
          "component": "Button",
          "child": "delete_trigger_text",
          "variant": "default",
          "action": {
            "event": {
              "name": "open_modal",
              "context": {}
            }
          }
        },
        {
          "id": "modal_desc",
          "component": "Text",
          "text": "Are you sure you want to delete your account? This action cannot be undone."
        },
        {
          "id": "confirm_btn_text",
          "component": "Text",
          "text": "Confirm Deletion"
        },
        {
          "id": "confirm_btn",
          "component": "Button",
          "child": "confirm_btn_text",
          "variant": "primary",
          "action": {
            "event": {
              "name": "confirm_deletion",
              "context": {}
            }
          }
        },
        {
          "id": "cancel_btn_text",
          "component": "Text",
          "text": "Cancel"
        },
        {
          "id": "cancel_btn",
          "component": "Button",
          "child": "cancel_btn_text",
          "variant": "borderless",
          "action": {
            "event": {
              "name": "cancel_deletion",
              "context": {}
            }
          }
        },
        {
          "id": "modal_content",
          "component": "Column",
          "children": [
            "modal_desc",
            "confirm_btn",
            "cancel_btn"
          ]
        },
        {
          "id": "delete_modal",
          "component": "Modal",
          "trigger": "delete_trigger_btn",
          "content": "modal_content"
        },
        {
          "id": "root",
